1	/** Pure mappers: validated raw `entire graph` JSON → domain value objects. */
2	import type { RawDiffResult, RawImpactResult, ImpactSectionName } from "./graph-schema.js";
3	import { IMPACT_SECTIONS } from "./graph-schema.js";
4	import type {
5	  ChangeSet,
6	  ChangeType,
7	  ChangedSymbol,
8	  RadiusNode,
9	  RadiusSection,
10	  SymbolRef,
11	} from "./model.js";
12	
13	const TEST_FILE = [
14	  /(^|\/)__tests__\//,
15	  /(^|\/)tests?\//,
16	  /\.(test|spec)\.[cm]?[jt]sx?$/,
17	  /_test\.go$/,
18	  /(^|\/)test_[^/]+\.py$/,
19	];
20	const TEST_NAME = [/^Test[A-Z_]/, /^test_/, /_test$/];
21	
22	function isTest(ref: SymbolRef): boolean {
23	  const f = (ref.file ?? "").replace(/\\/g, "/");
24	  if (TEST_FILE.some((re) => re.test(f))) return true;
25	  return TEST_NAME.some((re) => re.test(ref.name));
26	}
27	
28	const CHANGE_TYPE: Record<string, ChangeType> = {
29	  added: "added",
30	  removed: "removed",
31	  renamed: "renamed",
32	  signature_changed: "signature_changed",
33	  body_changed: "body_changed",
34	};
35	const NON_SYMBOL = new Set(["module", "file", "section", "document"]);
36	const NON_CODE_LANG = new Set(["Markdown", "JSON", "YAML", "TOML", "XML", "HTML"]);
37	// struct fields / vars / consts: a rename is technically an API change, but for a
38	// scope review the behavioural signal is method / function / class / type changes.
39	// entire-graph also inflates field dependent counts (every struct reference), so
40	// including them drowns the report. Keep them out of the change set.
41	const MEMBER_KINDS = new Set(["field", "variable", "property", "constant", "enum_member", "parameter"]);
42	
43	export function toChangeSet(raw: RawDiffResult): ChangeSet {
44	  const symbols: ChangedSymbol[] = [];
45	  const files = new Set<string>();
46	  for (const file of raw.files) {
47	    files.add(file.path);
48	    if (file.language && NON_CODE_LANG.has(file.language)) continue;
49	    for (const c of file.changes) {
50	      if (NON_SYMBOL.has(c.kind)) continue;
51	      if (MEMBER_KINDS.has(c.kind)) continue;
52	      const line = c.after_start_line ?? c.before_start_line;
53	      const name = c.new_name ?? c.name;
54	      symbols.push({
55	        ref: {
56	          name,
57	          qualifiedName: name,
58	          kind: c.kind,
59	          file: c.new_path ?? file.path,
60	          line: line && line > 0 ? line : undefined,
61	          external: false,
62	        },
63	        changeType:
64	          c.reconciliation === "RENAMED" ? "renamed" : (CHANGE_TYPE[c.type] ?? "unknown"),
65	        dependentsCount: c.dependents_count,
66	        oldSignature: c.old_signature,
67	        newSignature: c.new_signature,
68	      });
69	    }
70	  }
71	  return { base: raw.base, head: raw.head, checkpoint: raw.checkpoint, symbols, changedFiles: [...files] };
72	}
73	
74	const SECTION_RELATION: Record<ImpactSectionName, string> = {
75	  callers: "CALLED_BY",
76	  callees: "CALLS",
77	  type_consumers: "USES_TYPE",
78	  data_flows: "DATA_FLOWS",
79	  co_changes: "FILE_CHANGES_WITH",
80	  siblings: "SIBLING",
81	};
82	const SECTION_DOMAIN: Record<ImpactSectionName, RadiusSection> = {
83	  callers: "callers",
84	  callees: "callees",
85	  type_consumers: "type_consumers",
86	  data_flows: "data_flows",
87	  co_changes: "co_changes",
88	  siblings: "siblings",
89	};
90	
91	export function toRadiusNodes(raw: RawImpactResult, origin: string): RadiusNode[] {
92	  const out: RadiusNode[] = [];
93	  for (const section of IMPACT_SECTIONS) {
94	    for (const e of raw[section].entries) {
95	      const ep = e.endpoint;
96	      const qn = ep.qualified_name && ep.qualified_name.length > 0 ? ep.qualified_name : ep.name;
97	      const ref: SymbolRef = {
98	        name: ep.name,
99	        qualifiedName: qn,
100	        kind: ep.kind,
101	        file: ep.file_path,
102	        line: ep.start_line,
103	        external: ep.external ?? false,
104	      };
105	      const rel = e.relation?.toUpperCase();
106	      out.push({
107	        ref,
108	        section: SECTION_DOMAIN[section],
109	        relation:
110	          rel === "USES_TYPE" || rel === "PARAM_TYPE" || rel === "RETURNS_TYPE"
111	            ? rel
112	            : SECTION_RELATION[section],
113	        distance: e.depth && e.depth > 0 ? e.depth : 1,
114	        viaChain: e.via ? e.via.split(/\s*(?:->|,)\s*/).filter(Boolean) : [],
115	        originSymbols: [origin],
116	        isTest: isTest(ref),
117	      });
118	    }
119	  }
120	  return out;
121	}
