1	/** Domain value objects — the vocabulary every stage speaks. Pure. */
2	
3	export interface SymbolRef {
4	  readonly name: string;
5	  readonly qualifiedName: string;
6	  readonly kind: string | undefined;
7	  readonly file: string | undefined;
8	  readonly line: number | undefined;
9	  readonly external: boolean;
10	}
11	
12	export type ChangeType =
13	  | "added"
14	  | "removed"
15	  | "renamed"
16	  | "signature_changed"
17	  | "body_changed"
18	  | "unknown";
19	
20	export interface ChangedSymbol {
21	  readonly ref: SymbolRef;
22	  readonly changeType: ChangeType;
23	  readonly dependentsCount: number;
24	  readonly oldSignature: string | undefined;
25	  readonly newSignature: string | undefined;
26	}
27	
28	export interface ChangeSet {
29	  readonly base: string;
30	  readonly head: string;
31	  readonly checkpoint: string | undefined;
32	  readonly symbols: readonly ChangedSymbol[];
33	  readonly changedFiles: readonly string[];
34	}
35	
36	export type RadiusSection =
37	  | "callers"
38	  | "callees"
39	  | "type_consumers"
40	  | "data_flows"
41	  | "co_changes"
42	  | "siblings";
43	
44	export interface RadiusNode {
45	  readonly ref: SymbolRef;
46	  readonly section: RadiusSection;
47	  readonly relation: string;
48	  readonly distance: number;
49	  readonly viaChain: readonly string[];
50	  readonly originSymbols: readonly string[];
51	  readonly isTest: boolean;
52	}
53	
54	/** A call edge between two changed symbols (`from` calls `to`) — for the diagram. */
55	export interface OriginEdge {
56	  readonly from: string;
57	  readonly to: string;
58	}
59	
60	export interface BlastRadius {
61	  readonly origin: readonly ChangedSymbol[];
62	  readonly nodes: readonly RadiusNode[];
63	  readonly sectionTotals: Readonly<Record<RadiusSection, number>>;
64	  readonly originEdges: readonly OriginEdge[];
65	}
66	
67	export interface IntentModel {
68	  readonly source: string;
69	  readonly text: string;
70	  readonly keywords: readonly string[];
71	}
72	
73	export type Severity = "high" | "medium" | "low";
74	
75	export interface Finding {
76	  readonly symbol: SymbolRef;
77	  readonly severity: Severity;
78	  readonly reason: string;
79	  readonly dependentsCount: number;
80	  readonly evidence: readonly string[];
81	}
82	
83	export interface TestCandidate {
84	  readonly ref: SymbolRef;
85	  readonly distance: number;
86	  readonly covers: readonly string[];
87	}
88	
89	export interface TestPlan {
90	  readonly framework: string;
91	  readonly selected: readonly TestCandidate[];
92	  readonly command: string | null;
93	  readonly coverageGaps: readonly string[];
94	}
95	
96	export interface AnalysisReport {
97	  readonly schemaVersion: "1.0.0";
98	  readonly generatedAt: string;
99	  readonly range: { base: string; head: string; checkpoint: string | undefined };
100	  readonly intent: IntentModel | null;
101	  readonly changedSymbols: readonly ChangedSymbol[];
102	  readonly radius: BlastRadius;
103	  readonly findings: readonly Finding[];
104	  readonly testPlan: TestPlan;
105	}
106	
107	export function symbolKey(ref: Pick<SymbolRef, "qualifiedName" | "file">): string {
108	  return `${ref.file ?? "?"}::${ref.qualifiedName}`;
109	}
110	
111	export function loc(ref: Pick<SymbolRef, "file" | "line">): string | undefined {
112	  if (!ref.file) return undefined;
113	  return ref.line ? `${ref.file}:${ref.line}` : ref.file;
114	}
