1	/**
2	 * Fold the per-changed-symbol impact node lists into one blast radius.
3	 *  - dedupe by (file, qualifiedName): keep the SHORTEST distance, union origins
4	 *  - a node that is itself a changed symbol is the origin, not the blast — dropped
5	 *  - drop external callees (fmt.Errorf etc.) as review noise
6	 */
7	import type { BlastRadius, ChangedSymbol, OriginEdge, RadiusNode, RadiusSection } from "./model.js";
8	import { symbolKey } from "./model.js";
9	
10	function emptyTotals(): Record<RadiusSection, number> {
11	  return { callers: 0, callees: 0, type_consumers: 0, data_flows: 0, co_changes: 0, siblings: 0 };
12	}
13	
14	function merge(a: RadiusNode, b: RadiusNode): RadiusNode {
15	  const origins = new Set([...a.originSymbols, ...b.originSymbols]);
16	  const closer = b.distance < a.distance ? b : a;
17	  return {
18	    ...closer,
19	    originSymbols: [...origins],
20	    viaChain: closer.viaChain.length > 0 ? closer.viaChain : a.viaChain,
21	    isTest: a.isTest || b.isTest,
22	  };
23	}
24	
25	export function computeBlastRadius(
26	  origin: readonly ChangedSymbol[],
27	  nodeLists: readonly (readonly RadiusNode[])[],
28	): BlastRadius {
29	  const originKeys = new Set(origin.map((s) => symbolKey(s.ref)));
30	  const originNames = new Set(origin.map((s) => s.ref.qualifiedName));
31	  const byKey = new Map<string, RadiusNode>();
32	  const edgeSeen = new Set<string>();
33	  const originEdges: OriginEdge[] = [];
34	
35	  for (const list of nodeLists) {
36	    for (const node of list) {
37	      if (node.ref.external && node.section === "callees") continue;
38	      const key = symbolKey(node.ref);
39	      if (originKeys.has(key) || originNames.has(node.ref.qualifiedName)) {
40	        // one changed symbol calling another: keep it as an edge for the diagram
41	        if (node.section === "callers") {
42	          for (const o of node.originSymbols) {
43	            if (o === node.ref.qualifiedName || !originNames.has(o)) continue;
44	            const e = `${node.ref.qualifiedName} ${o}`;
45	            if (!edgeSeen.has(e)) {
46	              edgeSeen.add(e);
47	              originEdges.push({ from: node.ref.qualifiedName, to: o });
48	            }
49	          }
50	        }
51	        continue;
52	      }
53	      const existing = byKey.get(key);
54	      byKey.set(key, existing ? merge(existing, node) : node);
55	    }
56	  }
57	
58	  const nodes = [...byKey.values()].sort(
59	    (a, b) => a.distance - b.distance || a.ref.qualifiedName.localeCompare(b.ref.qualifiedName),
60	  );
61	  const sectionTotals = emptyTotals();
62	  for (const n of nodes) sectionTotals[n.section] += 1;
63	  return { origin: [...origin], nodes, sectionTotals, originEdges };
64	}
