1	/**
2	 * Scope-creep detection. The graph says what changed; the intent says what was
3	 * asked. A changed symbol whose name shares no vocabulary with the intent, and
4	 * that other code depends on, is flagged.
5	 *
6	 * Deliberately lexical, not embeddings — it has to be explainable to a reviewer
7	 * in one sentence: "this symbol shares no words with the ticket."
8	 */
9	import type { BlastRadius, ChangeSet, Finding, IntentModel, Severity } from "./model.js";
10	import { loc } from "./model.js";
11	
12	const STOP = new Set([
13	  "the", "and", "for", "with", "add", "adds", "added", "fix", "fixes", "update", "updates",
14	  "change", "changes", "make", "use", "using", "support", "new", "into", "endpoint", "so",
15	  "that", "this", "when", "get", "set", "run", "via", "per",
16	]);
17	
18	export interface SplitOptions {
19	  /** keep tokens shorter than 3 chars (dropped by default). */
20	  readonly keepShort?: boolean;
21	}
22	
23	export function splitIdent(s: string, opts: SplitOptions = {}): string[] {
24	  const parts = s
25	    .replace(/[/\\.]+/g, " ")
26	    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
27	    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
28	    .replace(/[_-]+/g, " ")
29	    .toLowerCase()
30	    .split(/\s+/)
31	    .filter(Boolean);
32	  return opts.keepShort ? parts : parts.filter((p) => p.length >= 2);
33	}
34	
35	function stem(w: string): string {
36	  return w.replace(/(ies)$/, "y").replace(/(ing|ed|ly|es|s|er|or)$/, "");
37	}
38	
39	export function keywords(text: string, extraTerms: readonly string[] = []): string[] {
40	  const out = new Set<string>();
41	  for (const w of [...splitIdent(text), ...extraTerms]) {
42	    if (w.length < 3 || STOP.has(w)) continue;
43	    const s = stem(w);
44	    if (s.length >= 3 && !STOP.has(s)) out.add(s);
45	  }
46	  return [...out].sort();
47	}
48	
49	function tokens(qualifiedName: string, file: string | undefined): Set<string> {
50	  const parts = [
51	    ...splitIdent(qualifiedName),
52	    ...(file ? splitIdent(file.replace(/\.[a-z0-9]+$/i, "")) : []),
53	  ].filter((p) => !["src", "internal", "pkg", "lib", "cmd", "test", "tests"].includes(p));
54	  const out = new Set<string>();
55	  for (const p of parts) {
56	    if (p.length < 3 || STOP.has(p)) continue;
57	    out.add(stem(p));
58	  }
59	  return out;
60	}
61	
62	function severity(deps: number): Severity {
63	  if (deps >= 15) return "high";
64	  if (deps >= 6) return "medium";
65	  return "low";
66	}
67	
68	export interface ScopeOptions {
69	  readonly maxOverlap?: number;
70	  readonly minDependents?: number;
71	  readonly wideThreshold?: number;
72	}
73	
74	export function detectScopeCreep(
75	  changeSet: ChangeSet,
76	  intent: IntentModel | null,
77	  radius: BlastRadius,
78	  opts: ScopeOptions = {},
79	): Finding[] {
80	  const maxOverlap = opts.maxOverlap ?? 0.15;
81	  const minDeps = opts.minDependents ?? 3;
82	  const wide = opts.wideThreshold ?? 8;
83	  const kw = new Set(intent?.keywords ?? []);
84	  const findings: Finding[] = [];
85	
86	  for (const s of changeSet.symbols) {
87	    if (s.changeType === "added") continue;
88	    const t = tokens(s.ref.qualifiedName, s.ref.file);
89	    const shared = [...t].filter((x) => kw.has(x));
90	    const overlap = t.size === 0 ? 1 : shared.length / t.size;
91	
92	    const keywordMiss = kw.size > 0 && overlap <= maxOverlap && s.dependentsCount >= minDeps;
93	    const wideReach = s.dependentsCount >= wide;
94	    if (!keywordMiss && !wideReach) continue;
95	
96	    const trail = radius.nodes
97	      .filter((n) => n.section === "callers" && n.originSymbols.includes(s.ref.qualifiedName) && !n.isTest)
98	      .slice(0, 3)
99	      .map((n) => n.ref.qualifiedName);
100	
101	    const reasons: string[] = [];
102	    if (keywordMiss) {
103	      reasons.push(
104	        shared.length === 0
105	          ? "no vocabulary overlap with the stated intent"
106	          : `weak overlap with the stated intent (only: ${shared.join(", ")})`,
107	      );
108	    }
109	    if (wideReach) {
110	      reasons.push(
111	        s.changeType === "signature_changed"
112	          ? `signature changed with ${s.dependentsCount} dependents — run tests first`
113	          : `wide-reaching change: ${s.dependentsCount} dependents`,
114	      );
115	    }
116	
117	    findings.push({
118	      symbol: s.ref,
119	      severity: severity(s.dependentsCount),
120	      reason: reasons.join("; "),
121	      dependentsCount: s.dependentsCount,
122	      evidence: [
123	        intent
124	          ? `intent (${intent.source}): "${intent.text.split("\n")[0]!.trim().slice(0, 100)}"`
125	          : "no stated intent",
126	        `changed — ${s.changeType.replace("_", " ")}, ${s.dependentsCount} dependents` +
127	          (loc(s.ref) ? ` — ${loc(s.ref)}` : ""),
128	        ...(trail.length ? [`reaches ${trail.join(" → ")}`] : []),
129	      ],
130	    });
131	  }
132	
133	  return findings.sort(
134	    (a, b) =>
135	      ({ high: 3, medium: 2, low: 1 })[b.severity] - ({ high: 3, medium: 2, low: 1 })[a.severity] ||
136	      b.dependentsCount - a.dependentsCount,
137	  );
138	}
