1	/**
2	 * AnalysisReport → a Markdown review comment.
3	 *
4	 * Layout: a shields.io badge strip, a Mermaid graph of the change and its
5	 * callers (findings in red), the scope table, a copy-paste test command, then
6	 * collapsed detail — evidence, the test rationale, the full node list. Every
7	 * symbol links to `file:line` when a repo blob-url base is supplied.
8	 */
9	import type { AnalysisReport, RadiusSection, SymbolRef } from "./model.js";
10	import { loc } from "./model.js";
11	
12	export interface RenderOptions {
13	  /** e.g. "https://github.com/org/repo/blob/<sha>" — makes locators clickable. */
14	  readonly repoBlobUrlBase?: string | undefined;
15	  /** draw the Mermaid diagram (default true). */
16	  readonly diagram?: boolean;
17	  readonly toolUrl?: string | undefined;
18	}
19	
20	const SEV_ICON = { high: "🔴", medium: "🟠", low: "🟡" } as const;
21	const SEV_COLOR = { high: "da3633", medium: "d29922", low: "bf8700" } as const;
22	
23	function short(ref: string): string {
24	  return /^[0-9a-f]{40}$/i.test(ref) ? ref.slice(0, 7) : ref;
25	}
26	
27	function badge(label: string, message: string, color: string): string {
28	  const enc = (s: string) =>
29	    encodeURIComponent(s.replace(/-/g, "--").replace(/_/g, "__").replace(/ /g, "_"));
30	  return `![${label}](https://img.shields.io/badge/${enc(label)}-${enc(message)}-${color})`;
31	}
32	
33	function moduleOf(file: string): string {
34	  const p = file.replace(/\\/g, "/").split("/");
35	  return p.slice(0, 2).join("/");
36	}
37	
38	export function renderMarkdown(report: AnalysisReport, opts: RenderOptions = {}): string {
39	  const r = report;
40	  const nodes = r.radius.nodes;
41	  const out: string[] = [];
42	
43	  const link = (ref: Pick<SymbolRef, "file" | "line">, text: string): string => {
44	    if (!ref.file) return text;
45	    if (!opts.repoBlobUrlBase) return `${text} \`${loc(ref)}\``;
46	    return `[${text}](${opts.repoBlobUrlBase}/${ref.file}${ref.line ? `#L${ref.line}` : ""})`;
47	  };
48	
49	  /* -------- summary numbers -------- */
50	  const files = new Set<string>();
51	  const modules = new Set<string>();
52	  const byRel: Record<string, number> = {};
53	  for (const n of nodes) {
54	    if (n.ref.file) {
55	      files.add(n.ref.file);
56	      modules.add(moduleOf(n.ref.file));
57	    }
58	    byRel[n.relation] = (byRel[n.relation] ?? 0) + 1;
59	  }
60	  const findingNames = new Set(r.findings.map((f) => f.symbol.qualifiedName));
61	  const maxSev = r.findings.reduce<"high" | "medium" | "low" | null>((a, f) => {
62	    const rank = { high: 3, medium: 2, low: 1 };
63	    return !a || rank[f.severity] > rank[a] ? f.severity : a;
64	  }, null);
65	
66	  out.push("<!-- blast-radius -->");
67	  out.push("## 🧨 Blast Radius");
68	  out.push("");
69	  const badges = [
70	    badge("blast radius", `${nodes.length} nodes`, "1f6feb"),
71	    badge("modules", String(modules.size), "1f6feb"),
72	    r.findings.length === 0
73	      ? badge("scope", "clean", "2da44e")
74	      : badge("scope", `${r.findings.length} findings`, maxSev ? SEV_COLOR[maxSev] : "d29922"),
75	    r.testPlan.coverageGaps.length > 0
76	      ? badge("tests", `${r.testPlan.selected.length} · ${r.testPlan.coverageGaps.length} gaps`, "bf8700")
77	      : badge("tests", `${r.testPlan.selected.length} selected`, "2da44e"),
78	    badge("intent", r.intent ? r.intent.source : "none", r.intent ? "8250df" : "8b949e"),
79	  ];
80	  out.push(badges.join(" "));
81	  out.push("");
82	
83	  if (r.intent) {
84	    const line1 = r.intent.text.split("\n")[0]!.trim().slice(0, 160);
85	    out.push(`> **Intent** — _${JSON.stringify(line1)}_  `);
86	    out.push(`> source: \`${r.intent.source}\`` + (r.range.checkpoint ? ` · \`${r.range.checkpoint}\`` : ""));
87	  } else {
88	    out.push("> **Intent** — none found. Scope drift can't be judged; showing radius + tests only.");
89	  }
90	  out.push("");
91	
92	  /* -------- mermaid -------- */
93	  const diagram = renderDiagram(r, findingNames, nodes.length);
94	  if (opts.diagram !== false && diagram) out.push(diagram, "");
95	
96	  /* -------- scope -------- */
97	  if (r.findings.length > 0) {
98	    out.push(`### ⚠️ Scope check — ${r.findings.length} change(s) look outside the ask`);
99	    out.push("");
100	    out.push("| | Changed symbol | Why | Dependents |");
101	    out.push("|--|--|--|--|");
102	    for (const f of r.findings) {
103	      out.push(`| ${SEV_ICON[f.severity]} | ${link(f.symbol, `\`${f.symbol.qualifiedName}\``)} | ${f.reason} | ${f.dependentsCount} |`);
104	    }
105	    out.push("");
106	    out.push("<details><summary>Evidence for these findings</summary>", "");
107	    for (const f of r.findings) {
108	      out.push(`**\`${f.symbol.qualifiedName}\`** — \`${loc(f.symbol) ?? "?"}\``);
109	      const seen = new Set<string>();
110	      for (const e of f.evidence) {
111	        if (seen.has(e)) continue;
112	        seen.add(e);
113	        out.push(`- ${e}`);
114	      }
115	      out.push("");
116	    }
117	    out.push("</details>", "");
118	  } else if (r.intent) {
119	    out.push("### ✅ Scope check — every change maps to the stated intent", "");
120	  }
121	
122	  /* -------- tests -------- */
123	  const tp = r.testPlan;
124	  if (tp.selected.length > 0) {
125	    const cover = tp.coverageGaps.length === 0 ? "covers every changed symbol" : `covers all but ${tp.coverageGaps.length}`;
126	    out.push(`### 🧪 Recommended tests — ${tp.selected.length}, ${cover}`, "");
127	    if (tp.command) out.push("```bash", tp.command, "```", "");
128	    out.push("<details><summary>Why these tests</summary>", "");
