170	function renderDiagram(
171	  r: AnalysisReport,
172	  findingNames: Set<string>,
173	  totalNodes: number,
174	): string | null {
175	  const cap = 18;
176	  const changedNames = new Set(r.changedSymbols.map((c) => c.ref.qualifiedName));
177	  const changed = r.changedSymbols.filter((c) => {
178	    if (c.changeType === "added" && !r.radius.nodes.some((n) => n.originSymbols.includes(c.ref.qualifiedName))) {
179	      return false;
180	    }
181	    if (c.ref.kind === "class" || c.ref.kind === "interface" || c.ref.kind === "type") {
182	      const prefix = `${c.ref.qualifiedName}.`;
183	      if ([...changedNames].some((n) => n.startsWith(prefix))) return false;
184	    }
185	    return true;
186	  });
187	  if (changed.length === 0) return null;
188	
189	  const callers = r.radius.nodes.filter((n) => n.section === "callers").sort((a, b) => a.distance - b.distance);
190	  if (callers.length === 0) return null;
191	
192	  const map = new Map<string, string>();
193	  const id = (name: string) => {
194	    const e = map.get(name);
195	    if (e) return e;
196	    const g = `n${map.size}`;
197	    map.set(name, g);
198	    return g;
199	  };
200	  const has = (name: string) => map.has(name);
201	
202	  const lines: string[] = ["```mermaid", "flowchart LR"];
203	  let count = 0;
204	  for (const c of changed) {
205	    if (count >= cap) break;
206	    lines.push(`  ${id(c.ref.qualifiedName)}["${mermaidLabel(c.ref.qualifiedName)}"]:::${findingNames.has(c.ref.qualifiedName) ? "finding" : "changed"}`);
207	    count++;
208	  }
209	  for (const e of r.radius.originEdges) {
210	    if (has(e.from) && has(e.to)) lines.push(`  ${id(e.from)} --> ${id(e.to)}`);
211	  }
212	  let callersShown = 0;
213	  const seen = new Set<string>();
214	  for (const n of callers) {
215	    if (count >= cap) break;
216	    const key = n.ref.qualifiedName;
217	    if (seen.has(key)) continue;
218	    const via = n.viaChain[n.viaChain.length - 1];
219	    const target = via && has(via) ? via : n.originSymbols[0];
220	    if (!target || !has(target)) continue;
221	    seen.add(key);
222	    if (!has(key)) {
223	      lines.push(`  ${id(key)}["${mermaidLabel(key)}"]:::${n.isTest ? "test" : "caller"}`);
224	      count++;
225	    }
226	    lines.push(`  ${id(key)} --> ${id(target)}`);
227	    callersShown++;
228	  }
229	  lines.push(
230	    "  classDef finding fill:#ffdcdc,stroke:#e5534b,color:#86181d;",
231	    "  classDef changed fill:#fff3d4,stroke:#d4a72c,color:#7a5c00;",
232	    "  classDef caller fill:#eef2f6,stroke:#8c959f,color:#1f2328;",
233	    "  classDef test fill:#e6f4ea,stroke:#4c9a5f,color:#1a4d2e;",
234	    "```",
235	  );
236	  const body = lines.join("\n");
237	  const legend = [
238	    body.includes(":::finding") ? "🟥 changed — flagged, outside the stated intent" : "",
239	    body.includes(":::changed") ? "🟨 changed — in scope" : "",
240	    body.includes(":::caller") ? "⬜ not changed — calls the change, may be affected" : "",
241	    body.includes(":::test") ? "🟩 not changed — a covering test" : "",
242	  ].filter(Boolean);
243	  const note = `call paths only — ${changed.length} changed symbol(s) + ${callersShown} of the ${totalNodes}-node blast radius. Callees, types, co-change files &amp; siblings are in the “Full blast radius” table below.`;
244	  return `${body}\n<sub>${legend.join("  ·  ")}<br>arrow: A → B means A calls B · ${note}</sub>`;
245	}
