1	/**
2	 * The `review` use-case — the pipeline, spelled out.
3	 *   diff → impact per changed symbol → fold → { scope check · test selection } → report
4	 * Depends only on a GraphProvider + an intent resolver.
5	 */
6	import { computeBlastRadius } from "./domain/blast-radius.js";
7	import type { AnalysisReport } from "./domain/model.js";
8	import { renderMarkdown, type RenderOptions } from "./domain/render.js";
9	import { detectScopeCreep, type ScopeOptions } from "./domain/scope-creep.js";
10	import { selectTests } from "./domain/test-select.js";
11	import { resolveIntent, type IntentContext } from "./adapters/intent.js";
12	import type { CommitRange, GraphProvider } from "./ports.js";
13	
14	export interface ReviewRequest {
15	  readonly range: CommitRange;
16	  readonly repo: string;
17	  readonly prTitle?: string | undefined;
18	  readonly prBody?: string | undefined;
19	  readonly scope?: ScopeOptions;
20	  readonly maxTests?: number | undefined;
21	  readonly maxSymbols?: number | undefined;
22	  readonly render?: RenderOptions;
23	  readonly log?: (msg: string) => void;
24	}
25	
26	export async function runReview(
27	  graph: GraphProvider,
28	  req: ReviewRequest,
29	): Promise<{ report: AnalysisReport; markdown: string }> {
30	  const log = req.log ?? (() => {});
31	
32	  if ("warmIndex" in graph && typeof graph.warmIndex === "function") {
33	    log("warming the graph index…");
34	    await (graph as { warmIndex: () => Promise<void> }).warmIndex();
35	  }
36	
37	  const changeSet = await graph.diff(req.range);
38	  log(`${changeSet.symbols.length} changed symbol(s) across ${changeSet.changedFiles.length} file(s)`);
39	
40	  // analyse the widest-reaching changes first, cap the rest — one impact call
41	  // per symbol, run serially so a cold index isn't rebuilt N times in parallel
42	  const maxSymbols = req.maxSymbols ?? 25;
43	  const ordered = [...changeSet.symbols].sort((a, b) => b.dependentsCount - a.dependentsCount);
44	  const nodeLists = [];
45	  for (const s of ordered.slice(0, maxSymbols)) {
46	    try {
47	      const r = await graph.impact({ name: s.ref.qualifiedName, file: s.ref.file });
48	      nodeLists.push(r.nodes);
49	    } catch (e) {
50	      log(`impact skipped for ${s.ref.qualifiedName}: ${(e as Error).message}`);
51	    }
52	  }
53	  const radius = computeBlastRadius(changeSet.symbols, nodeLists);
54	  log(`blast radius: ${radius.nodes.length} node(s)`);
55	
56	  const intentCtx: IntentContext = {
57	    repo: req.repo,
58	    head: req.range.head,
59	    base: req.range.base,
60	    prTitle: req.prTitle,
61	    prBody: req.prBody,
62	  };
63	  const { intent, checkpoint } = await resolveIntent(intentCtx);
64	  log(intent ? `intent from ${intent.source}` : "no stated intent found");
65	
66	  const findings = detectScopeCreep(changeSet, intent, radius, req.scope);
67	  const testPlan = selectTests(radius, changeSet.symbols, req.maxTests ?? 12);
68	
69	  const report: AnalysisReport = {
70	    schemaVersion: "1.0.0",
71	    generatedAt: new Date().toISOString(),
72	    range: { base: req.range.base, head: req.range.head, checkpoint: checkpoint ?? changeSet.checkpoint },
73	    intent,
74	    changedSymbols: changeSet.symbols,
75	    radius,
76	    findings,
77	    testPlan,
78	  };
79	  return { report, markdown: renderMarkdown(report, req.render ?? {}) };
80	}
