8	export interface CliOptions {
9	  /** how to invoke the graph: `["entire","graph"]` or `["/path/to/entire-graph"]`. */
10	  readonly argv0: readonly string[];
11	  readonly repo: string;
12	  readonly profile?: "fast" | "full";
13	  /** query the committed tree — reuses a warm `index --head` cache (much faster in CI). */
14	  readonly head?: boolean;
15	  readonly timeoutMs?: number;
16	}
