18	export class EntireGraphCliProvider implements GraphProvider {
19	  readonly kind = "entire-graph-cli";
20	  constructor(private readonly opts: CliOptions) {}
21	
22	  private async run(args: string[], timeoutMs?: number): Promise<unknown> {
23	    const [bin, ...pre] = this.opts.argv0;
24	    const r = await execa(bin!, [...pre, ...args], {
25	      timeout: timeoutMs ?? this.opts.timeoutMs ?? 240_000,
26	      stripFinalNewline: true,
27	    });
28	    return JSON.parse(String(r.stdout ?? ""));
29	  }
30	
31	  /** Prewarm one committed-tree cache variant so `impact --head` is fast. */
32	  async warmIndex(): Promise<void> {
33	    try {
34	      await execa(this.opts.argv0[0]!, [...this.opts.argv0.slice(1), "index", "--repo", this.opts.repo, "--head", "--profile", this.opts.profile ?? "fast"], {
35	        timeout: 600_000,
36	      });
37	    } catch {
38	      /* best effort — impact still works without it, just slower */
39	    }
40	  }
41	
42	  async diff(range: CommitRange): Promise<ChangeSet> {
43	    const raw = await this.run(
44	      ["diff", "--repo", this.opts.repo, "--base", range.base, "--head", range.head, "--json"],
45	      600_000,
46	    );
47	    return toChangeSet(rawDiffResult.parse(raw));
48	  }
49	
50	  async impact(q: ImpactQuery): Promise<{ nodes: ReturnType<typeof toRadiusNodes>; disambiguation: boolean }> {
51	    const args = [
52	      "impact", "--repo", this.opts.repo, "--symbol", q.name,
53	      "--format", "json", "--depth", "2", "--profile", this.opts.profile ?? "full",
54	    ];
55	    if (q.file) args.push("--file", q.file);
56	    if (this.opts.head) args.push("--head");
57	    const raw = await this.run(args);
58	    const parsed = rawImpactResult.parse(raw);
59	    return { nodes: toRadiusNodes(parsed, q.name), disambiguation: parsed.disambiguation_required };
60	  }
61	}
