export function extractCompleteness(raw: RawCompletenessInput): Completeness {
  const failures = [...(raw.partial_failures ?? [])];
  const warnings = [...(raw.warnings ?? [])];
  const errorWarnings = warnings.filter(isErrorNote);
  const advisory = warnings.filter((w) => !isErrorNote(w));

  const unresolved = new Set<string>();
  for (const n of [...failures, ...errorWarnings]) {
    if (n.file_path) unresolved.add(norm(n.file_path));
  }

  const notes = [
    ...failures.map(noteLine),
    ...errorWarnings.map(noteLine),
    ...advisory
      .filter((w) => w.effect_on_semantic_completeness)
      .map((w) => `${w.code ?? "note"}: ${w.effect_on_semantic_completeness}`),
